# 3. TERMINAL LOGIC & TRANSFORMATION
def build_akuru(glyph_name, svg_d_string):
    """Processes primary consonants (Akuru) at 1:1 scale."""
    glyph = font.newGlyph(glyph_name)
    pen = glyph.getPen()
    parsePath(svg_d_string, pen)
    print(f"[ALPHA] {glyph_name.upper()} ingested at 100% scale.")

def build_scaled_fili(glyph_name, svg_d_string):
    """Applies the 729-NEUTRAL-01 Mandate: 70% Scale Transform for vowel diacritics."""
    # Mathematical matrix for exact 0.7 reduction
    scale_matrix = Transform(0.7, 0, 0, 0.7, 0, 0)
    
    glyph = font.newGlyph(glyph_name)
    pen = glyph.getPen()
    
    # Ingesting through the TransformPen to force 70% scale
    transform_pen = TransformPen(pen, scale_matrix)
    parsePath(svg_d_string, transform_pen)
    
    # Anchoring for GPOS alignment at the 1266 baseline
    glyph.appendAnchor(dict(x=1024, y=1266, name="_top"))
    print(f"[GAMMA] {glyph_name.upper()} transformed at 70% scale. Anchors locked.")

